package com.vandorlabs.client;

import com.vandorlabs.gear.*;
import com.vandorlabs.gear.core.*;
import com.vandorlabs.gear.track.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.block.model.*;
import net.minecraft.client.shader.Framebuffer;
import net.minecraft.item.*;
import net.minecraft.nbt.*;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraftforge.common.property.IExtendedBlockState;
import java.awt.image.BufferedImage;
import java.io.File;
import java.lang.reflect.Field;
import java.util.*;

/** Actual one-block style meshes, authored bounds, rotating Track normals and visible error dialog. */
public final class TrackClientChecks {
    private static void require(boolean value,String message){if(!value)throw new IllegalStateException("Track client: "+message);}
    public static void run(Minecraft mc,File output)throws Exception{
        int visible=0;for(TrackBlock block:TrackRegistry.BLOCKS){Item item=Item.getItemFromBlock(block);if(item.getCreativeTabs().length>0)visible++;else require(block!=TrackRegistry.COMPACT,"canonical Track remains available");}require(visible==1,"only one creative/JEI Track registry item");int cases=0;
        for(int style=0;style<3;style++)for(EnumFacing facing:EnumFacing.HORIZONTALS)for(int mask:new int[]{0,1,5,15})for(TrackAppearance.Mount mount:new TrackAppearance.Mount[]{TrackAppearance.Mount.NONE,TrackAppearance.Mount.SOCKET,TrackAppearance.Mount.TOP_HIGH}){
            TrackAppearance appearance=new TrackAppearance(mask,mount,0,0);net.minecraft.block.state.IBlockState state=((IExtendedBlockState)TrackRegistry.COMPACT.getDefaultState().withProperty(TrackBlock.FACING,facing)).withProperty(TrackAppearance.PROPERTY,appearance).withProperty(TrackAppearance.STYLE,style);IBakedModel model=mc.getBlockRendererDispatcher().getModelForState(((IExtendedBlockState)state).getClean());List<BakedQuad> quads=model.getQuads(state,null,0);require(!quads.isEmpty(),"canonical Track emits selected style "+style+" facing="+facing+" assembled="+state.getValue(TrackBlock.ASSEMBLED)+" model="+model.getClass().getName());AxisAlignedBB bounds=TrackGeometry.bounds(com.vandorlabs.gear.track.core.TrackTopology.Style.values()[style],facing,appearance);double[] actual={Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY};for(BakedQuad q:quads){require(q.getSprite()!=mc.getTextureMapBlocks().getMissingSprite(),"selected style native sprite resolves");int[] data=q.getVertexData();for(int v=0;v<4;v++)for(int axis=0;axis<3;axis++){double p=Float.intBitsToFloat(data[v*data.length/4+axis]);actual[axis]=Math.min(actual[axis],p);actual[axis+3]=Math.max(actual[axis+3],p);}}double[] expected={bounds.minX,bounds.minY,bounds.minZ,bounds.maxX,bounds.maxY,bounds.maxZ};for(int i=0;i<6;i++)require(Math.abs(actual[i]-expected[i])<2e-5,"native rotated geometry and selection/collision bounds agree style="+style+" side="+facing+" component="+i+" native="+actual[i]+" bound="+expected[i]);cases++;
        }
        BufferedImage sheet=new BufferedImage(768,256,BufferedImage.TYPE_INT_ARGB);for(int style=0;style<3;style++){GearTileEntity arm=arm(mc,style,true,0);BufferedImage image=render(mc,arm);int ink=0;for(int y=0;y<256;y++)for(int x=0;x<256;x++){int rgb=image.getRGB(x,y);sheet.setRGB(style*256+x,y,rgb);if((rgb&0xffffff)!=0x203040)ink++;}require(ink>800,"actual rotating Track assembly visibly renders style="+style);}
        javax.imageio.ImageIO.write(sheet,"png",new File(output,"shot_track_rotating_styles.png"));
        for(boolean rotate:new boolean[]{false,true}){GearTileEntity arm=arm(mc,0,rotate,0);GearMotion.Vec a=arm.pose(0).transformFootVertex(.5,-.5,.5),b=arm.pose(0).transformFootVertex(.5,.5,.5);require(rotate?Math.abs(b.y-a.y)<1e-8:Math.abs(b.y-a.y-1)<1e-8,"actual saved Track payload rotate/level mode controls native foot transform");TrackAppearance selected=TrackGeometry.onArm(TrackAppearance.SINGLE);require(selected.mount==TrackAppearance.Mount.NONE&&TrackParts.forCell(com.vandorlabs.gear.track.core.TrackTopology.Style.COMPACT,EnumFacing.NORTH,selected).size()==1,"rotating swivel replaces Track socket instead of drawing overlapping joint");}
        errorDialog(mc,output);System.out.println("[vandorlabs][reprolab] track-client PASS canonical-one-creative/JEI item savedstyle emitted-mesh-bound-comparisons="+cases+" actual rotated styles FBO joint replacement rotate/level normals and compact ERROR dialog");
    }
    private static GearTileEntity arm(Minecraft mc,int style,boolean rotate,double progress){
        BlockPos root=new BlockPos(2,2,2);GearTileEntity template=new GearTileEntity();template.setPos(root);NBTTagCompound tag=template.writeToNBT(new NBTTagCompound());tag.setBoolean("GearController",true);tag.setBoolean("GearOperational",true);tag.setBoolean("GearConfigured",true);tag.setInteger("GearHeight",1);tag.setInteger("GearFootFacing",EnumFacing.NORTH.getHorizontalIndex());tag.setString("GearKind","TRACK");tag.setString("GearMode",rotate?"ROTATE":"ROTATE_LEVEL");tag.setString("GearDirection","NORTH");tag.setBoolean("ArmRotatePayload",rotate);tag.setDouble("GearProgress",progress);tag.setBoolean("GearTargetDeployed",progress==1);NBTTagList feet=new NBTTagList();feet.appendTag(new NBTTagIntArray(new int[]{0,-1,0}));feet.appendTag(new NBTTagIntArray(new int[]{0,-1,1}));tag.setTag("GearFeet",feet);
        List<com.vandorlabs.vehicle.VehicleStructure.Cell> cells=new ArrayList<>();cells.add(new com.vandorlabs.vehicle.VehicleStructure.Cell(root,GearRegistry.GEAR_SWING_ARM.getDefaultState().withProperty(GearBlock.ASSEMBLED,true),tag));for(int z=0;z<2;z++){BlockPos at=root.down().south(z);TrackTile track=new TrackTile();track.setPos(at);track.style(style);NBTTagCompound data=track.writeToNBT(new NBTTagCompound());data.setLong("GearOwnerOffset",root.subtract(at).toLong());cells.add(new com.vandorlabs.vehicle.VehicleStructure.Cell(at,TrackRegistry.COMPACT.getDefaultState().withProperty(TrackBlock.ASSEMBLED,true),data));}com.vandorlabs.vehicle.VehicleWorld view=new com.vandorlabs.vehicle.VehicleWorld(mc.world,com.vandorlabs.vehicle.VehicleStructure.display(cells));GearTileEntity arm=(GearTileEntity)view.getTileEntity(root);require(arm.isOperational()&&arm.assembly().kind()==GearTopology.FootKind.TRACK,"isolated native Track controller fixture");return arm;
    }
    private static BufferedImage render(Minecraft mc,GearTileEntity arm){Framebuffer frame=new Framebuffer(256,256,true);projection(-1.8,1.8,-1.8,1.8);try(TurntableRenderState saved=new TurntableRenderState()){clear(frame);GlStateManager.rotate(25,1,0,0);GlStateManager.rotate(35,0,1,0);com.vandorlabs.gear.client.GearRenderer renderer=new com.vandorlabs.gear.client.GearRenderer();renderer.setRendererDispatcher(net.minecraft.client.renderer.tileentity.TileEntityRendererDispatcher.instance);renderer.render(arm,-.5,0,-.5,1,-1,1);org.lwjgl.opengl.GL11.glFinish();return ScreenShotHelper.createScreenshot(256,256,frame);}finally{finish(mc,frame);}}
    private static void errorDialog(Minecraft mc,File output)throws Exception{Field error=GearTileEntity.class.getDeclaredField("lastError");error.setAccessible(true);net.minecraft.inventory.Container previous=mc.player.openContainer;try{for(int[] size:new int[][]{{320,240},{460,340}}){GearTileEntity arm=arm(mc,0,true,1);error.set(arm,"Clear the Track stroke before deploying");GuiModularGear gui=new GuiModularGear(new com.vandorlabs.container.ContainerModularGear(arm));gui.inventorySlots.windowId=-93;gui.setWorldAndResolution(mc,size[0],size[1]);Framebuffer frame=new Framebuffer(size[0],size[1],true);projection(0,size[0],size[1],0);try(TurntableRenderState saved=new TurntableRenderState()){clear(frame);gui.drawScreen(-1,-1,0);BufferedImage image=ScreenShotHelper.createScreenshot(size[0],size[1],frame);int red=0;for(int y=Math.max(0,gui.getGuiTop()+228);y<Math.min(size[1],gui.getGuiTop()+251);y++)for(int x=gui.getGuiLeft()+12;x<gui.getGuiLeft()+gui.getXSize()-12;x++)if((image.getRGB(x,y)&0xffffff)==0xff8888)red++;require(red>25,"server Track deploy error is visibly red in compact dialog");javax.imageio.ImageIO.write(image,"png",new File(output,"shot_track_error_dialog_"+size[0]+".png"));}finally{finish(mc,frame);}}}finally{mc.player.openContainer=previous;org.lwjgl.input.Keyboard.enableRepeatEvents(false);}}
    private static void projection(double l,double r,double b,double t){GlStateManager.matrixMode(5889);GlStateManager.pushMatrix();GlStateManager.loadIdentity();GlStateManager.ortho(l,r,b,t,-1000,1000);GlStateManager.matrixMode(5888);GlStateManager.pushMatrix();}
    private static void clear(Framebuffer frame){frame.bindFramebuffer(true);GlStateManager.loadIdentity();GlStateManager.depthMask(true);GlStateManager.clearColor(32/255F,48/255F,64/255F,1);GlStateManager.clear(16640);GlStateManager.enableDepth();GlStateManager.enableTexture2D();GlStateManager.disableLighting();GlStateManager.disableCull();GlStateManager.disableBlend();GlStateManager.enableAlpha();GlStateManager.alphaFunc(516,.1F);GlStateManager.color(1,1,1,1);Minecraft.getMinecraft().entityRenderer.disableLightmap();}
    private static void finish(Minecraft mc,Framebuffer frame){GlStateManager.popMatrix();GlStateManager.matrixMode(5889);GlStateManager.popMatrix();GlStateManager.matrixMode(5888);frame.deleteFramebuffer();mc.getFramebuffer().bindFramebuffer(true);}
    private TrackClientChecks(){}
}
